1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Scenario = {
8	  customer: { yearsWithMHPCO: number };
9	  steps: { op: string; items: Item[] }[];
10	};
11	
12	export type ScenarioResult = {
13	  results: { premium: number }[];
14	};
15	
16	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	};
24	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
25	const CURSE_SURCHARGE_PERCENT = 50;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
28	const PROCESSING_FEE = 5;
29	
30	const percentOf = (amount: number, percent: number): number =>
31	  (amount * percent) / 100;
32	
33	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
34	
35	const BLOCK_SIZE = 3;
36	const BLOCK_BASE_PREMIUM = 60;
37	
38	/** Groups of items of the same type — "alike" in the MHPCO's terms. */
39	type AlikeItems = { type: string; count: number };
40	
41	const groupAlikeItems = (items: Item[]): AlikeItems[] =>
42	  [
43	    ...items.reduce(
44	      (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
45	      new Map<string, number>(),
46	    ),
47	  ].map(([type, count]) => ({ type, count }));
48	
49	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
50	
51	const basePremiumForAlikeItems = ({ type, count }: AlikeItems): number =>
52	  formsBuildingBlock(count)
53	    ? BLOCK_BASE_PREMIUM
54	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
55	
56	const policyBasePremium = (items: Item[]): number =>
57	  groupAlikeItems(items)
58	    .map(basePremiumForAlikeItems)
59	    .reduce((total, alikeItemsPremium) => total + alikeItemsPremium, 0);
60	
61	const itemBasePremium = (item: Item): number =>
62	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
63	
64	const isHighlyEnchanted = (item: Item): boolean =>
65	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
66	
67	/** Item-specific surcharges stack additively. */
68	const itemSurchargePercent = (item: Item): number =>
69	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
70	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
71	
72	/**
73	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
74	 * premium — unlike policy-wide modifiers, which apply to the policy base.
75	 */
76	const totalItemSurcharges = (items: Item[]): number =>
77	  items.reduce(
78	    (total, item) =>
79	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
80	    0,
81	  );
82	
83	/**
84	 * Policy-wide modifiers are percentages of the POLICY base premium — unlike
85	 * item-specific modifiers, which apply to the affected item's own base.
86	 */
87	const policySurcharges = (basePremium: number): number =>
88	  percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
89	
90	const quotePremium = (items: Item[]): number => {
91	  const basePremium = policyBasePremium(items);
92	  return roundInMHPCOsFavour(
93	    basePremium +
94	      totalItemSurcharges(items) +
95	      policySurcharges(basePremium) +
96	      PROCESSING_FEE,
97	  );
98	};
99	
100	export const runScenario = (scenario: Scenario): ScenarioResult => ({
101	  results: scenario.steps.map((step) => ({
102	    premium: quotePremium(step.items),
103	  })),
104	});
