/** Groups of items of the same type — "alike" in the MHPCO's terms. */
type AlikeItems = { type: string; count: number };

const groupAlikeItems = (items: Item[]): AlikeItems[] =>
  [
    ...items.reduce(
      (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
      new Map<string, number>(),
    ),
  ].map(([type, count]) => ({ type, count }));

const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;

const basePremiumForAlikeItems = ({ type, count }: AlikeItems): number =>
  formsBuildingBlock(count)
    ? BLOCK_BASE_PREMIUM
    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];

const policyBasePremium = (items: Item[]): number =>
  groupAlikeItems(items)
    .map(basePremiumForAlikeItems)
    .reduce((total, alikeItemsPremium) => total + alikeItemsPremium, 0);

